import sqlite3

def log_call(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@log_call
def fetch_data(user_input):
    db = sqlite3.connect(':memory:')
    return db.execute(f"SELECT * FROM data WHERE key = '{user_input}'").fetchall()

